int checks=0;
void Check(bool value,string why){if(!value)throw new Exception(why);checks++;}
void Reject(Action run,string why){try{run();}catch(ArgumentException){checks++;return;}catch(InvalidOperationException){checks++;return;}throw new Exception("Missing rejection: "+why);}
Dictionary<string,object> Args()=>new(){{"entityId",51L}};
var raw=new GameObject{name="SushiFish"};raw.transform.position=new(){x=8.4f,y=.5f,z=-7.2f};
