using var dll=AssemblyDefinition.ReadAssembly(args[0]);
var type=dll.MainModule.GetType("SuperchargedPatch.Authoring.Modules.RegistryObserverModule");
var calls=type.Methods.Where(m=>m.HasBody).SelectMany(m=>m.Body.Instructions).Select(i=>i.Operand).OfType<MethodReference>().Select(m=>m.FullName).ToArray();
Check(calls.Count(m=>m.Contains("Hpmv.OutputData::set_EntityRegistry"))==1,"Compiled native module has one observer queue publication site");
Check(!calls.Any(m=>m.Contains("NativeSceneMetadata::Refresh")||m.Contains("CommitFrame")||m.Contains("RequestFullObservation")||m.Contains("UnityEngine.Transform::set_")||m.Contains("UnityEngine.Rigidbody::set_")),"Compiled module has no broad refresh, frame commit, cache reset or native physics setters");
Check(calls.Any(m=>m.Contains("SpawnableEntityCollectionExt::GetSpawnables")),"Compiled code uses existing native ordered spawn-list reader");
Check(calls.Count(m=>m.Contains("EntityRetirementMessageSender::SendMessageToRetireEntity(System.UInt32)"))==1,"Compiled observer uses one existing framework-only retirement publication site");
Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(new{ok=true,checks,gameCalls=0,module=args[0],scope="Focused observation/guard fixtures plus compiled frozen-X module call audit; native delivery is measured separately."}));
